div.script:
function LiveChatChecker() {
    LiveChatWidget.init();
    LiveChatWidget.call('hide_greeting');
    var pageMode = LiveChatWidget.get('state').visibility;
    if (pageMode == "maximized") {
        LiveChatWidget.call('minimize');
        LiveChatWidget.call('hide');
    }
    else {
        LiveChatWidget.call('maximize');
    }
    return false;
}

