const searchBoxInner = document.querySelector('.search-box-inner');
const searchBoxToggle = document.getElementById('searchboxtoggle');
document.addEventListener('click', function (event) {
    if (!searchBoxInner.contains(event.target)) {
        document.body.classList.remove('click');
    } else {
        // Optionally handle click inside the container, e.g., close the box or toggle visibility
        // searchBoxInner.classList.toggle('open');  // Toggle visibility (if needed)
    }
});
        
		
		
		
		$(document).ready(function () {
    $('#skipNavigationButton').on('click', function () {
        $(this).hide(); // hide the #skipNavigationButton
        $('body').addClass('contentSkiped'); // add class to 
        $('#searchInputId').focus(); // focus input if needed
    });

    // Click outside .search-box removes 'contentSkiped' from body
    $(document).on('click', function (e) {
        if (!$(e.target).closest('.search-box').length && !$(e.target).is('#skipNavigationButton')) {
            $('body').removeClass('contentSkiped');
        }
    });

    // Pressing ESC key removes 'contentSkiped' from body
    $(document).on('keydown', function (e) {
        if (e.key === "Escape" || e.keyCode === 27) {
            $('body').removeClass('contentSkiped');
			$('.searchbox-toggle').removeClass('open');
            $('#skipNavigationButton').hide();
        }
    });
});

