window.onload = function () {
    setTimeout(function () {
        LiveChatWidget.call('hide_greeting');
        //console.log('hide_greeting after page window.onload 1');
        LiveChatWidget.call('hide');
    }, 2900); // Delay of 3 seconds
    setTimeout(function () {
        LiveChatWidget.call('hide_greeting');
        //console.log('hide_greeting after page window.onload 2');
        LiveChatWidget.call('hide');
    }, 1500); // Delay of 1 seconds
};
